import {allowsRacks} from './working-areas.js';
import {rackStats} from './racks.js';
export const rackKeys=['length','width','height','tiers','pallets'];
export function matchingRackType(types,value){return types.find(t=>rackKeys.every(k=>(t[k]??(k==='tiers'?1:0))===value[k]));}
export function rackPanel(state,esc,fmt){return `<section class="rackGroups"><h2>List of Racks</h2>${state.shapes.filter(s=>s.layer==='section').map(s=>{const stats=rackStats(state,s.id);return `<article class="rackGroup"><div class="rackGroupHeading"><b>${esc(s.name)}</b><button data-add-section-rack="${esc(s.id)}" ${allowsRacks(s)?'':'disabled'}>Add ＋</button></div>${allowsRacks(s)?`<p class="rackGroupSpace">${fmt(stats.used)} / ${fmt(stats.total)} m² · ${fmt(stats.free)} m² free</p>`:'<p class="rackGroupSpace">Rack placement disabled</p>'}${state.racks.filter(r=>r.sectionId===s.id).map((r,i)=>`<div class="rackCompactRow"><button data-open-rack="${esc(r.id)}">${esc(r.name||'Rack '+(i+1))}</button><details class="rackMenu"><summary aria-label="Rack actions">⋯</summary><div><button data-open-rack="${esc(r.id)}">Edit</button><button data-remove-rack="${esc(r.id)}">Delete</button></div></details></div>`).join('')||'<p class="rackGroupSpace">No racks yet</p>'}</article>`}).join('')||'<p class="empty">Create a section in the bottom bar to add racks.</p>'}</section>`;}
